import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html'
})
export class LoginComponent {

  form: FormGroup;
  loading = false;
  error = '';

  constructor(
    private fb: FormBuilder,
    private auth: AuthService,
    private router: Router
  ) {
    this.form = this.fb.group({
      email:    ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });

    // Already logged in → redirect
    if (this.auth.isLoggedIn()) {
      this.redirectByRole();
    }
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';

    this.auth.login(this.form.value).subscribe({
      next: () => this.redirectByRole(),
      error: err => {
        this.error = err.error?.message ?? 'Invalid email or password';
        this.loading = false;
      }
    });
  }

  private redirectByRole(): void {
    const role = this.auth.getRole();
    switch (role) {
      case 'ADMIN':        this.router.navigate(['/admin']);        break;
      case 'RECEPTIONIST': this.router.navigate(['/receptionist']); break;
      case 'DOCTOR':       this.router.navigate(['/doctor']);       break;
    }
  }
}
<div style="min-height:100vh;display:flex;align-items:center;justify-content:center;background:#1a3c5e;">
  <div class="card" style="width:380px;">
    <div style="text-align:center;margin-bottom:28px;">
      <h2 style="color:#1a3c5e;font-size:22px;">Smart Hospital Queue</h2>
      <p style="color:#6c757d;font-size:14px;margin-top:4px;">Staff Login</p>
    </div>

    <div *ngIf="error" class="alert alert-danger">{{ error }}</div>

    <form [formGroup]="form" (ngSubmit)="submit()">
      <div class="form-group">
        <label>Email</label>
        <input type="email" formControlName="email" placeholder="staff@hospital.com">
        <span class="error-msg"
          *ngIf="form.get('email')?.invalid && form.get('email')?.touched">
          Valid email is required
        </span>
      </div>

      <div class="form-group">
        <label>Password</label>
        <input type="password" formControlName="password" placeholder="Password">
        <span class="error-msg"
          *ngIf="form.get('password')?.invalid && form.get('password')?.touched">
          Password is required
        </span>
      </div>

      <button class="btn btn-primary" style="width:100%;margin-top:8px;"
        type="submit" [disabled]="loading">
        {{ loading ? 'Signing in...' : 'Sign In' }}
      </button>
    </form>

    <div style="text-align:center;margin-top:20px;">
      <a routerLink="/patient" style="color:#007bff;font-size:13px;">
        Patient Portal — Check Queue Status
      </a>
    </div>
  </div>
</div>
